  factories(first: 1) { poolCount totalValueLockedUSD }
  pools(first: 12, orderBy: totalValueLockedUSD, orderDirection: desc, where: { totalValueLockedUSD_gt: 0 }) {
    id
    feeTier
    totalValueLockedUSD
    volumeUSD
    token0 { symbol }
    token1 { symbol }
    poolDayData(first: 1, orderBy: date, orderDirection: desc) { volumeUSD feesUSD }
  }
}"}

